package africa.growtogether.platform.ewe.task; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ewe_task_events") public class WorkflowTaskEvent { @Id private UUID id=UUID.randomUUID(); @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="task_id",nullable=false) private UUID taskId; @Column(name="event_type",nullable=false,length=50) private String eventType; @Column(name="actor_user_id") private UUID actorUserId; @Column(name="details",nullable=false,columnDefinition="jsonb") private String details="{}"; @Column(name="occurred_at",nullable=false) private Instant occurredAt=Instant.now(); protected WorkflowTaskEvent(){} public WorkflowTaskEvent(UUID t,UUID task,String type,UUID actor,String details){tenantId=t;taskId=task;eventType=type;actorUserId=actor;this.details=details==null?"{}":details;} public UUID getId(){return id;} public UUID getTaskId(){return taskId;} public String getEventType(){return eventType;} public Instant getOccurredAt(){return occurredAt;} }